    "algoritm": "Проверяемый параметр:Удаленность (дальность пешеходного подхода) до ближайшего остановочного пункта общественного пассажирского транспорта.Ожидаемое значение параметра:Максимальная дальность пешеходного подхода до ближайшего остановочного пункта общественного пассажирского транспорта должна составлять:·       не более 500 м — в общем случае;·       не более 250 м — от объектов массового посещения, расположенных в общегородском центре;·       не более 150 м — от поликлиник, стационарных медицинских организаций и отделений социального обслуживания;·       не более 400 м — от проходных предприятий, расположенных в производственных и коммунально-складских зонах;·       не более 800 м — от главного входа в зоны массового отдыха и спорта.Условия проверки параметра:Проверка выполняется для объектов капитального строительства, для которых СП 42.13330.2016 устанавливает нормативы пешеходной доступности до остановок общественного пассажирского транспорта.При наличии специального назначения объекта применяется соответствующий специальный норматив, установленный п. 11.24 СП 42.13330.2016, вместо общего норматива.",
