    "algoritm": "Проверяемый параметр:соответствии нормам инсоляции (в части влияния размещаемого объекта на продолжительность инсоляции для нормируемых помещений и территорий)Ожидаемое значение параметра:соблюдение норматива центральной светоклиматической зоны (широты от 58° до 48° с.ш.), предусматривающего минимальную продолжительность непрерывной инсоляции 2 часа для нормируемых помещений.Условие проверки:во всех случая проектирования кроме:а) административные и офисные здания (за исключением помещений, для которых специальные отраслевые нормы устанавливают требования);б) производственные здания;в) складские здания;г) гаражи и автостоянки;д) инженерные сооружения и объекты коммунальной инфраструктуры;е) торговые, спортивные и большинство общественных зданий, если нормативами для них не установлены требования по инсоляции;ж) технические помещения (индивидуальные тепловые пункты, насосные, венткамеры, электрощитовые, серверные и т.п.)",
